{"hypotheses": [
  {
    "name": "Organizational Capital + Deferred Revenue Anomaly",
    "mechanism": "Firms with high organizational capital (OrgCap) and increasing deferred revenue (DelDRC) may have superior future prospects that are underappreciated by investors. Combining these captures persistent intangible investment AND upfront monetization, which together signal both operational scalability and customer trust, leading to returns that neither captures alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "DelDRC"},
        {"weight": -0.5, "primitive": "NetEquityFinance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Industry Asset Concentration and Analyst Over-optimism",
    "mechanism": "Stocks in highly asset-concentrated industries (HerfAsset) with simultaneously high analyst optimism (AOP) and low analyst forecast dispersion (ForecastDispersion) are often overvalued, leading to subsequent mean reversion. The composite exploits market participants' herding in crowded, hyped sectors where consensus is unusually tight.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "HerfAsset"},
        {"weight": -0.5, "primitive": "AOP"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "AOP", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Patent Intensity and Operating Leverage",
    "mechanism": "Firms with high patent-to-R&D ratios (PatentsRD) and high operating leverage (OPLeverage) are poised to disproportionately benefit from scalable innovation. The combination captures those best at converting R&D into protection AND who have operating structures to magnify those gains.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "PatentsRD"},
        {"weight": 1.0, "primitive": "OPLeverage"},
        {"weight": -0.5, "primitive": "DebtIssuance"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "PatentsRD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Customer Momentum and Real Estate Backing",
    "mechanism": "Firms with strong customer momentum (iomom_cust) and large real estate holdings (realestate) are likely to experience persistent demand shocks that are both supported by tangible asset backing and less vulnerable to short-term supply disruptions, creating a unique defensive growth profile.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "realestate"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Short-term Reversal with Inventory Adjustment",
    "mechanism": "Short-term price reversals (STreversal) are more persistent when firms also aggressively adjust their inventory levels (ChInvIA), as such adjustments often indicate that fundamental shifts support the price action, not just market overreaction.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "STreversal"},
        {"weight": 0.5, "primitive": "ChInvIA"},
        {"weight": -0.5, "primitive": "EarningsForecastDisparity"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "STreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.45,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Option Market Sentiment and Employment Growth",
    "mechanism": "Stocks with high put-call volatility spread (CPVolSpread) and robust employment growth (hire) reflect both market skepticism and real economic expansion. The combination identifies firms where pessimistic sentiment is likely unwarranted, creating a reversal opportunity.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "CPVolSpread"},
        {"weight": 1.0, "primitive": "hire"},
        {"weight": 0.5, "primitive": "BrandInvest"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "opposite_sign"}
    ],
    "expected_annualized_sharpe": 0.52,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "Analyst Downward Revision and Tangible Asset Dominance",
    "mechanism": "Stocks experiencing significant downward analyst revisions (DownRecomm) but with high asset tangibility (tang) are systematically underpriced because real asset backing provides a floor, often overlooked during negative sentiment episodes.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "DownRecomm"},
        {"weight": 1.0, "primitive": "tang"},
        {"weight": 0.5, "primitive": "CashProd"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "DownRecomm", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Pension Funding and Organizational Complexity",
    "mechanism": "Firms with strong pension funding status (FR) but high conglomerate complexity (retConglomerate) are less likely to face hidden future financial distress. The composite exploits that well-funded, diversified firms are underappreciated when investors focus on apparent complexity risks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "FR"},
        {"weight": 0.5, "primitive": "retConglomerate"},
        {"weight": -0.5, "primitive": "CompEquIss"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"}
    ],
    "expected_annualized_sharpe": 0.54,
    "expected_decay_half_life_months": 28
  }
]}
